(* Golden vectors for the chunk-44 [Tn_network] port: the
   [4B LE uncompressed_len][4B LE compressed_len][snappy_frame(bcs)] wire
   envelope of telcoin-network @ 31cc4e90
   (crates/network-libp2p/src/codec.rs).  Shared the way batch_vectors.ml,
   header_vectors.ml and snappy_vectors.ml are: NOT listed in test/dune's
   (names ...), so dune links it into every test binary, and nothing but the
   stdlib is used, so it drags in no library.

   THE ORACLE.  Every row below was emitted on 2026-08-12 by the chunk-44
   Rust oracle harness (~/Documents/telcoin-ocaml-chunk44-harness/oracle,
   subcommand `emit-wire`, kept output wire-rows.txt), built against the
   crates telcoin-network @ 31cc4e90 pins in its Cargo.lock: snap 1.1.1
   (Cargo.lock:11163-11164) and bcs 0.1.6 (Cargo.lock:1701-1702).  The
   harness re-declares the message types verbatim and mirrors codec.rs's
   encode_message (112-154) and decode_message (32-105) in the SAME order of
   operations (oracle/src/wire.rs).

   POSITIVE_CONTROL.  The same harness binary re-derives all seven frozen
   chunk-41 [Batch] rows of test/batch_vectors.ml from its own verbatim Batch
   declaration and compares them byte for byte (`chunk44-oracle control`): v1
   through v7 all MATCH.  So the harness that produced the rows below is the
   same one that produced the already-trusted batch column.

   WHAT THE ROWS PIN.
   - [max_compress_len_rows]: snap::raw::max_compress_len, the ceiling
     decode check #2 applies to the compressed prefix.  The 1 MiB row is the
     worked example of GT:294-297, 1_048_576 -> 1_223_370.
   - [wire_rows]: seven real messages at all three stages (bcs payload,
     snappy frame stream, full wire message).  The port must DECODE every
     [wire_hex] back to its [bcs_hex]; it need not reproduce [frame_hex] or
     [wire_hex] byte for byte, because compressed bytes are never
     canonicalized, hashed or signed (GT:355-356) and this port's frame
     encoder emits uncompressed chunks only.
   - [sweep_rows]: the same envelope over mod-251 payloads at 0, 1, 100 and
     the 65536-byte snappy chunk boundary.  The 1_048_575-byte row carries no
     hex: the harness prints "-" above its 4096-byte FULL_HEX_LIMIT, so that
     size is covered in the other direction, by the reverse gate that feeds
     this port's own output back through snap.
   - [doctored_rows]: GT:339's doctored prefix.  A wire message whose
     declared uncompressed_len is SHORTER than the true payload is ACCEPTED
     at the frame layer: [.take(declared)] truncates, and check #6 compares
     the truncated length against the same declared value, so both pass.  The
     failure comes later, from BCS, and only when the prefix is not itself a
     complete message.  These rows are the port's proof that it copies Rust's
     real semantics rather than the stale test comment at codec_tests.rs:234.

   Hex decoding is [Snappy_vectors.unhex], the fail-closed decoder shared by
   the chunk-44 suites. *)


let wire_max_message_size = 1048576

(* [(n, max_compress_len n)] straight from snap 1.1.1's own function
   (compress.rs:42-53): 32 + n + n / 6, integer division. *)
let max_compress_len_rows : (int * int) list =
  [ (0, 32); (1, 33); (6, 39); (65536, 76490); (65537, 76491); (1048576, 1223370) ]

