(* roaring 0.10.12 NEVER EMITS a run container: [serialize_into]
   unconditionally writes the no-run cookie (serialization.rs:67).  This row is
   therefore hand-built to the format and VALIDATED by the Rust decoder, which
   read back the ten values below.  The port's decoder must accept it; the
   port's encoder, like Rust's, need not produce it. *)
let roaring_run_hex = "3b300000010000090002000000040064000400"

let roaring_run_field_hex = "133b300000010000090002000000040064000400"

let roaring_run_values = [ 0; 1; 2; 3; 4; 100; 101; 102; 103; 104 ]

(* The BOUNDARY run: one container, one run [start = 0xfff0, len = 0x000f],
   whose last value is exactly 0xffff.  [s.checked_add(len)] just fits, so the
   Rust decoder reads it back as the sixteen values 65520..65535
   (card=16, max=65535). *)
let roaring_run_boundary_hex = "3b30000001000000000100f0ff0f00"
let roaring_run_boundary_values = List.init 16 (fun i -> 65520 + i)

(* Three inputs the Rust decoder REJECTS, with its own message. *)
let roaring_neg_rows : (string * string * string) list =
  [
    ("unknown_cookie", "00000000", "ERR unknown cookie value");
    ("truncated", "3a30000001", "ERR failed to fill whole buffer");
    (* The boundary row with [len] raised to 0xffff, so [start + len] leaves
       the u16 key space and serialization.rs:229 aborts the decode.  Without
       that test the run would spill sixteen values into the NEXT container's
       range (65520..131055). *)
    ("run_start_len_overflow", "3b30000001000000000100f0ffffff", "ERR invalid data");
  ]

(* Gossipsub message ids, computed by bs58 0.5.1 exactly as
   libp2p-gossipsub 0.49.4's default message_id_fn does (GT:565).  [seq_hex] is
   hexadecimal because the two largest rows, 2^63 and u64::MAX, have no signed
   decimal reading: they are what catches a [%%Ld] rendering. *)
type msgid_row = {
  m_name : string;
  source_hex : string option;  (** [None] is the absent-source case. *)
  seq_hex : string option;  (** [None] means the message carried no number. *)
  id : string;  (** What Rust computed. *)
}

